#!/usr/bin/env python3
"""Apply the hand edits of the benchmark to two downloaded original images.

In two images, markers that revealed the answer were removed:
  images/165.jpg  ultrasound, the two calipers marking the embryo
  images/197.png  CT, the labels Ao, PA, RV and LV

First save both originals (`source_url` in the dataset) under these names,
then run this script once from the repository root. It edits both files in
place and skips a file that is already edited. It downloads nothing.

Usage:
    python scripts/apply_image_redactions.py [--images-dir images]
"""

import argparse
import base64
import gzip
from pathlib import Path

import numpy as np
from PIL import Image

# Edited pixels per image: base64-encoded gzip of uint16 rows [y, x, R, G, B]
EDITS = {
    "165.jpg": (
        (630, 412),
        "",
    ),
    "197.png": (
        (485, 483),
        "",
    ),
}


def decode_edits(encoded: str) -> np.ndarray:
    data = np.frombuffer(gzip.decompress(base64.b64decode(encoded)), dtype="<u2")
    return data.reshape(-1, 5)


def main() -> None:
    parser = argparse.ArgumentParser(description="Apply the hand edits to the two original images")
    parser.add_argument("--images-dir", type=Path, default=Path("images"))
    args = parser.parse_args()

    for filepath, (size, encoded) in EDITS.items():
        path = args.images_dir / filepath
        image = Image.open(path).convert("RGB")
        if image.size != size:
            raise SystemExit(f"{path}: expected the original image of size {size}, found {image.size}")
        pixels = np.array(image)
        edits = decode_edits(encoded)
        ys, xs, rgb = edits[:, 0], edits[:, 1], edits[:, 2:].astype(np.uint8)
        if np.abs(pixels[ys, xs].astype(int) - rgb).mean() < 3:
            print(f"{path}: already edited, skipped")
            continue
        pixels[ys, xs] = rgb
        if path.suffix == ".png":
            Image.fromarray(pixels).save(path)
        else:
            Image.fromarray(pixels).save(path, quality=95)
        print(f"{path}: {len(edits):,} pixels edited")


if __name__ == "__main__":
    main()
